mapper.select:
SELECT ti.id, ti.title, ti.scope, ti.content_type, ti.category_id, ic.name AS category_name, ti.views, ti.created_at, festival_period.start_date, festival_period.end_date FROM travel_info ti JOIN info_categories ic ON ic.id = ti.category_id LEFT JOIN info_periods festival_period ON festival_period.id = ( SELECT period_candidate.id FROM info_periods period_candidate WHERE period_candidate.info_id = ti.id AND ti.content_type = 'FESTIVAL' ORDER BY period_candidate.start_date ASC, period_candidate.end_date ASC, period_candidate.id ASC LIMIT 1 ) AND festival_period.info_id = ti.id
ti.scope = #{scope}
AND ti.content_type = #{contentType}
AND ti.category_id = #{categoryId}
ORDER BY ti.created_at DESC, ti.id DESC

